function boardStatusSettings(listId){let saved={};try{saved=JSON.parse(listById(listId)?.status_settings||'{}');}catch{}return {...Object.fromEntries(Object.entries(statusNames).map(([id,label])=>[id,{label,color:statusColors[id]}])),...saved};}
