function subitemStatusId(listId,child){const settings=subitemStatusSettings(listId),original=sourceSubitemLabel(child),lower=original.toLowerCase();if(original&&!child.status_touched){const importedStatus=['done','completed','complete','paid','funded','yes','checked','delivered','closed'].includes(lower)?'done':['working on it','in progress','started','it','processing','active'].includes(lower)?'doing':['stuck','waiting','on hold','pending'].includes(lower)?'waiting':'todo';if((child.status||'todo')===importedStatus){const match=Object.entries(settings).find(([,value])=>value.label.toLowerCase()===lower);if(match)return match[0];}}return child.status||(child.done?'done':'todo');}
function subitemStatusOptions(listId,child){const settings=subitemStatusSettings(listId),current=subitemStatusId(listId,child),blank=child.status_blank||(!sourceSubitemLabel(child)&&!child.status_touched);return `<option value="" style="background:#fff;color:#323338" ${blank?'selected':''}></option>`+Object.entries(settings).map(([id,value])=>`<option value="${esc(id)}" style="background:${esc(value.color)};color:#fff" ${id===current&&!blank?'selected':''}>${esc(value.label)}</option>`).join('');}
