function visibleTasks() {
  let tasks = data.tasks.filter(t=>view==='trash'?!!t.deleted_at&&!t.converted_into:view==='archived'?!!t.archived_at&&!t.deleted_at&&!listById(t.list_id)?.deleted_at:!t.deleted_at&&!t.archived_at&&!listById(t.list_id)?.deleted_at);
  if (view==='completed') tasks=tasks.filter(t=>t.status==='done');
  else if (view==='today') tasks=tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<=data.today);
  else if (view==='upcoming') tasks=tasks.filter(t=>t.status!=='done'&&t.due_date>data.today);
  else if (listById(view)) tasks=tasks.filter(t=>t.list_id===view);
  if(statusFilter) tasks=tasks.filter(t=>t.status===statusFilter);
  if(priorityFilter) tasks=tasks.filter(t=>t.priority===priorityFilter);
  if(personFilter) tasks=tasks.filter(t=>personFilter==='unassigned'?!t.assignee:t.assignee===auth.username);
  if(search.trim()) { const q=search.toLowerCase().trim(); tasks=tasks.filter(t=>[t.title,t.notes,t.category,listById(t.list_id)?.name,...t.checklist.map(c=>c.title)].some(v=>v?.toLowerCase().includes(q))); }
  const p={high:0,medium:1,low:2,none:3};
  return tasks.sort((a,b)=>sort==='title'?a.title.localeCompare(b.title):sort==='priority'?p[a.priority]-p[b.priority]:sort==='status'?Object.keys(statusNames).indexOf(a.status)-Object.keys(statusNames).indexOf(b.status):sort==='smart'?(a.due_date||'9999').localeCompare(b.due_date||'9999'):b.created_at.localeCompare(a.created_at));
}
function makeGroups(tasks) {
  const groups = new Map(), currentList=listById(view), filtered=search.trim()||statusFilter||priorityFilter||personFilter;
  const add=(key,name,color,defaults)=>{if(!groups.has(key))groups.set(key,{key,name,color,defaults,tasks:[]});};
  if(groupBy==='status') Object.entries(statusLabelsFor(currentList?.id)).forEach(([id,name])=>add(id,name,statusColorFor(currentList?.id,id),{status:id,list_id:currentList?.id||data.lists.find(l=>!l.deleted_at)?.id}));
  if(groupBy==='group'&&currentList&&!filtered) {
    (data.groups||[]).filter(g=>g.list_id===view).forEach(g=>add(g.name,g.name,g.color,{list_id:view,category:g.name}));
  }
  for(const t of tasks) {
    const board=listById(t.list_id); let key,name,color,defaults;
    if(groupBy==='status'){key=t.status;name=statusLabelFor(t.list_id,key);color=statusColorFor(t.list_id,key);defaults={list_id:currentList?.id||t.list_id,status:key};}
    else if(groupBy==='board'||!currentList){key=t.list_id;name=board?.name||'Items';color=groupColors[data.lists.indexOf(board)%groupColors.length];defaults={list_id:t.list_id};}
    else {key=t.category;name=t.category||'Items';color=(data.groups||[]).find(g=>g.list_id===view&&g.name===key)?.color||groupColors[groups.size%groupColors.length];defaults={list_id:view,category:t.category};}
    add(key,name,color,defaults);groups.get(key).tasks.push(t);
  }
  if(!tasks.length&&!filtered&&!isArchive()&&groupBy==='group'){
    if(currentList&&!groups.size)add('','Items',groupColors[0],{list_id:view});
    else if(!currentList)data.lists.filter(l=>!l.deleted_at).forEach((l,i)=>add(l.id,l.name,groupColors[i%groupColors.length],{list_id:l.id}));
  }
  return [...groups.values()];
}
let renderedGroups=[];
