  $('#filter-summary').innerHTML=statusFilter||priorityFilter||personFilter||search?`<div class="filter-summary">Showing ${tasks.length} matching items<button class="quiet-link" data-action="clear-filters">Clear filters ${icon('close')}</button></div>`:'';
