function selectedSubitemRows(){return data.tasks.flatMap(task=>task.checklist.filter(child=>selectedSubitems.has(subitemSelectionKey(task,child))).map(child=>({task,child})));}
async function bulkSubitemAction(action){
  const rows=selectedSubitemRows();if(!rows.length)return;
  if(action==='export'){
    const csv=['Board,Parent,Subitem,Status,Person,Date',...rows.map(({task,child})=>[listById(task.list_id)?.name,task.title,child.title,subitemStatusSettings(task.list_id)[subitemStatusId(task.list_id,child)]?.label||'',child.assignee||'',child.due_date||''].map(v=>'"'+String(v||'').replaceAll('"','""')+'"').join(','))].join('\r\n');
    const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='subitems.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;
  }
  if(action==='move'){
    if(new Set(rows.map(r=>r.task.list_id)).size>1){notify('Select subitems from one board to move them.');return;}
    const first=rows[0].task,choices=data.tasks.filter(t=>t.list_id===first.list_id&&!t.deleted_at&&!t.archived_at&&!rows.some(r=>r.task.id===t.id));
    small.innerHTML=`<div class="dialog-head"><h2 id="small-heading">Move ${rows.length} subitems</h2><button class="icon-button" data-action="close-small" aria-label="Close">${icon('close')}</button></div><div class="dialog-body"><label class="field">Choose a parent item<input id="parent-search" type="search" placeholder="Search items" autocomplete="off"></label><div id="parent-results" class="parent-results"></div><div class="form-error" role="alert"></div></div>`;
    const paint=()=>{const q=$('#parent-search',small).value.toLowerCase();$('#parent-results',small).innerHTML=choices.filter(t=>t.title.toLowerCase().includes(q)).slice(0,50).map(t=>`<button data-action="choose-bulk-subitem-parent" data-parent-id="${t.id}">${esc(t.title)}</button>`).join('')||'<p class="hint">No matching items on this board.</p>';};small.showModal();$('#parent-search',small).oninput=paint;paint();$('#parent-search',small).focus();return;
  }
  let count=0;const undo=[];
  try{
    if(action==='convert')for(const {task,child} of rows){await api(`tasks/${task.id}/subitems/${child.id}/convert-to-item`,'POST',{});count++;}
    else for(const taskId of [...new Set(rows.map(r=>r.task.id))]){
      const task=data.tasks.find(t=>t.id===taskId),ids=new Set(rows.filter(r=>r.task.id===taskId).map(r=>r.child.id));
      let checklist;
      if(action==='duplicate')checklist=task.checklist.flatMap(c=>ids.has(c.id)?[c,{...c,id:crypto.randomUUID(),title:c.title+' (copy)',source_id:''}]:[c]);
      else if(action==='archive')checklist=task.checklist.map(c=>ids.has(c.id)?{...c,archived_at:new Date().toISOString()}:c);
      else checklist=task.checklist.filter(c=>!ids.has(c.id));
      undo.push({taskId,checklist:task.checklist});await api(`tasks/${taskId}`,'PATCH',{checklist,version:task.version});count+=ids.size;
    }
    selectedSubitems.clear();await refresh();notify(`${count} subitems ${action==='duplicate'?'duplicated':action==='archive'?'archived':action==='delete'?'deleted':'converted'}.`,action==='delete'||action==='archive'?async()=>{for(const entry of undo){const task=data.tasks.find(t=>t.id===entry.taskId);await api(`tasks/${task.id}`,'PATCH',{checklist:entry.checklist,version:task.version});}await refresh();}:undefined);
  }catch(e){await refresh();handleError(e);}
}
