function inlineRename(button,current,max,save){
  const input=document.createElement('input');input.className='inline-rename';input.value=current;input.maxLength=max;input.setAttribute('aria-label',`Rename ${current}`);button.replaceWith(input);input.focus();input.select();
  let finished=false;const finish=async commit=>{if(finished)return;finished=true;const value=input.value.trim();if(!commit||!value||value===current){render();return;}input.disabled=true;try{await save(value);await refresh();notify('Name updated.');}catch(e){handleError(e);await refresh();}};
  input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();finish(true);}else if(e.key==='Escape'){e.preventDefault();finish(false);}};
  input.onblur=()=>finish(true);
}
