document.addEventListener('contextmenu',event=>{
  if(!auth||editor.open||small.open)return;
  const row=event.target.closest('.subitem-row,.item-row');if(!row)return;
  const task=data.tasks.find(t=>t.id===row.closest('[data-id]')?.dataset.id);if(!task||task.deleted_at||task.archived_at)return;
  event.preventDefault();popTask=task;popSubIndex=row.classList.contains('subitem-row')?Number(row.dataset.subindex):-1;
  showPopover({getBoundingClientRect:()=>({left:event.clientX,bottom:event.clientY})},popSubIndex>=0?subitemContextMenu():itemContextMenu());
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePopover();if(!auth||editor.open||small.open||!$('#popover').hidden||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName))return;if(e.key==='/'){e.preventDefault();$('#search')?.focus();}if(e.key==='n'){e.preventDefault();openEditor();}});
window.addEventListener('resize',closePopover);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&auth&&!editor.open&&!small.open&&$('#popover').hidden&&!document.activeElement?.matches('input,textarea,select'))refresh().catch(handleError);});
init();
